#include <bits/stdc++.h>
using namespace std;

const int MOD = 998244353;


int main() {
	// your code goes here
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    
    int t;
    cin >> t;
    while(t--){
        int n;
        cin >> n;
        
        vector<int> a(n+1);
        vector<vector<int>> pos(n+1);
        
        for(int i = 1;i <= n;i++){
            cin >> a[i];
            pos[a[i]].push_back(i);
        }
        
        vector<long long> dp(1,1);
        
        for(int v = 1;v <= n;v++){
            vector<long long> ndp(v+1,0);
            
            for(int l = 0;l < (int)dp.size();l++){
                if(!dp[l])continue;
                
                int r = v - 1 - l;
                
                int L = l + 1;
                int R = n - r;
                int P = L;
                
                bool ok = true;
                
                for(int i : pos[v]){
                   int pre = min(i,L)+max(0,i-(n-r))-(P <= i);
                   int suf = max(0,L-i+1) + max(0,n-max(i,n-r+1)+1) - (P >= i);
                   if(!((P <= i && pre == (i-1)/2) || (P >= i && suf == (n-i)/2))){
                       ok = false;
                       break;
                   }
                }
                
                if(ok){
                    ndp[l+1] = (ndp[l+1] +dp[l]) % MOD;
                }
                
                if(L != R){
                    int A = l;
                    int B = r+1;
                    P = R;
                    
                    ok = true;
                    
                    for(int i : pos[v]){
                        int pre = min(i,A) + max(0,i-(n-B)) - (P <= i);
                        int suf = max(0,A-i+1) + max(0,n-max(i,n-B + 1) + 1) - (P >= i);
                        
                        if(!((P <= i && pre == (i-1)/2) || (P >= i && suf == (n-i)/2))){
                            ok = false;
                            break;
                        }
                    }
                    
                    if(ok){
                        ndp[l] = (ndp[l] + dp[l])%MOD;
                    }
                }
            }
            dp = move(ndp);
        }
        long long ans = 0;
        for(long long x : dp){
            ans = (ans+x)%MOD;
        }
        
        cout << ans << '\n';
    }
    return 0;
}
